* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  background: #f4f6f9;
  color: #333;
}

h1 {
  text-align: center;
  padding: 18px 0 6px;
  font-size: 1.6rem;
  color: #1a1a2e;
}

.container {
  display: flex;
  gap: 24px;
  padding: 12px 24px 24px;
  max-width: 1600px;
  margin: 0 auto;
  align-items: flex-start;
}

/* ---------- Bubble chart panel ---------- */
.chart-panel {
  flex: 1 1 55%;
  min-width: 0;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  padding: 16px;
}

.chart-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 8px;
  color: #444;
}

#bubble-chart {
  width: 100%;
  position: relative;
}

#bubble-chart svg {
  display: block;
  width: 100%;
  height: auto;
}

/* Bubble labels */
.bubble-label {
  pointer-events: none;
  font-size: 10px;
  font-weight: 600;
  fill: #fff;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Bubble selection ring */
circle.selected {
  stroke: #222;
  stroke-width: 3px;
}

/* Legend */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin-top: 10px;
  padding: 0 4px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.78rem;
  color: #555;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

/* ---------- Tooltip ---------- */
.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(30, 30, 50, 0.92);
  color: #fff;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.82rem;
  line-height: 1.45;
  max-width: 280px;
  opacity: 0;
  transition: opacity 0.15s;
  z-index: 100;
}

.tooltip .tt-ticker {
  font-weight: 700;
  font-size: 0.92rem;
}

.tooltip .tt-name {
  margin-top: 2px;
}

.tooltip .tt-sector {
  margin-top: 2px;
  opacity: 0.8;
}

/* ---------- Table panel ---------- */
.table-panel {
  flex: 1 1 45%;
  min-width: 0;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  padding: 16px;
  max-height: 720px;
  overflow-y: auto;
}

.table-panel h2 {
  font-size: 1.05rem;
  margin-bottom: 8px;
  color: #444;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #f0f2f5;
  text-align: left;
  padding: 8px 10px;
  font-weight: 600;
  border-bottom: 2px solid #d0d4da;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
}

#stock-table thead th:hover {
  background: #e2e6ec;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background 0.12s;
}

#stock-table tbody tr:hover {
  background: #f0f4fa;
}

#stock-table tbody tr.highlighted {
  background: #dbeafe;
}

#stock-table td {
  padding: 7px 10px;
  border-bottom: 1px solid #e8eaee;
  white-space: nowrap;
}

#stock-table td:last-child {
  text-align: right;
}

