// ---------------------------------------------------------------------------
// Stock Bubble Chart + Data Table  (D3 v6)
// ---------------------------------------------------------------------------

(function () {
  "use strict";

  // Sector colour palette
  const sectorColors = {
    "Information Technology": "#4e79a7",
    Industry: "#f28e2b",
    Energy: "#e15759",
    Financial: "#76b7b2",
    ETF: "#999999",
  };

  // Format helpers
  function fmtMarketCap(val) {
    if (val == null || isNaN(val) || val === "") return "—";
    const n = +val;
    if (n >= 1e12) return (n / 1e12).toFixed(2) + "T";
    if (n >= 1e9) return (n / 1e9).toFixed(2) + "B";
    if (n >= 1e6) return (n / 1e6).toFixed(2) + "M";
    return n.toLocaleString();
  }

  // -----------------------------------------------------------------------
  // Load data
  // -----------------------------------------------------------------------
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    const data = raw.map(function (d) {
      return {
        ticker: d.ticker,
        name: d["full name"],
        sector: d.sector,
        marketCap: d.marketCap ? +d.marketCap : null,
        country: d.country || null,
        website: d.website || null,
      };
    });

    drawBubbleChart(data);
    drawTable(data);
  });

  // -----------------------------------------------------------------------
  // Shared selection state
  // -----------------------------------------------------------------------
  let selectedTicker = null;

  function selectTicker(ticker) {
    selectedTicker = selectedTicker === ticker ? null : ticker;

    // Bubble highlight
    d3.selectAll("#bubble-chart circle")
      .classed("selected", function (d) {
        return d && d.ticker === selectedTicker;
      });

    // Table highlight
    d3.selectAll("#stock-table tbody tr")
      .classed("highlighted", function () {
        return this.dataset.ticker === selectedTicker;
      });

    // Scroll selected table row into view
    if (selectedTicker) {
      const row = document.querySelector(
        '#stock-table tbody tr[data-ticker="' + selectedTicker + '"]'
      );
      if (row) row.scrollIntoView({ block: "nearest", behavior: "smooth" });
    }
  }

  // -----------------------------------------------------------------------
  // Bubble chart
  // -----------------------------------------------------------------------
  function drawBubbleChart(data) {
    const container = document.getElementById("bubble-chart");
    const width = 760;
    const height = 600;

    const svg = d3
      .select(container)
      .append("svg")
      .attr("viewBox", "0 0 " + width + " " + height)
      .attr("preserveAspectRatio", "xMidYMid meet");

    // Tooltip
    const tooltip = d3
      .select(container)
      .append("div")
      .attr("class", "tooltip");

    // Radius scale  (market cap -> radius)
    const caps = data.filter(function (d) { return d.marketCap; }).map(function (d) { return d.marketCap; });
    const rScale = d3
      .scaleSqrt()
      .domain([d3.min(caps), d3.max(caps)])
      .range([12, 52]);

    const ETF_RADIUS = 14;

    function radius(d) {
      return d.marketCap ? rScale(d.marketCap) : ETF_RADIUS;
    }

    // Sector positions for clustering
    const sectors = Object.keys(sectorColors);
    const sectorCenters = {};
    const cols = 3;
    const rows = Math.ceil(sectors.length / cols);
    sectors.forEach(function (s, i) {
      const col = i % cols;
      const row = Math.floor(i / cols);
      sectorCenters[s] = {
        x: width * (col + 1) / (cols + 1),
        y: height * (row + 1) / (rows + 1),
      };
    });

    // Force simulation
    const simulation = d3
      .forceSimulation(data)
      .force(
        "x",
        d3.forceX(function (d) { return sectorCenters[d.sector].x; }).strength(0.35)
      )
      .force(
        "y",
        d3.forceY(function (d) { return sectorCenters[d.sector].y; }).strength(0.35)
      )
      .force(
        "collide",
        d3.forceCollide(function (d) { return radius(d) + 2; }).strength(1).iterations(3)
      )
      .force("charge", d3.forceManyBody().strength(-5))
      .on("tick", ticked);

    // Draw bubbles
    const node = svg
      .selectAll("g.node")
      .data(data)
      .enter()
      .append("g")
      .attr("class", "node");

    node
      .append("circle")
      .attr("r", function (d) { return radius(d); })
      .attr("fill", function (d) { return sectorColors[d.sector]; })
      .attr("fill-opacity", 0.85)
      .attr("stroke", "#fff")
      .attr("stroke-width", 1)
      .style("cursor", "pointer")
      .on("click", function (event, d) {
        selectTicker(d.ticker);
      })
      .on("mouseenter", function (event, d) {
        if (d.sector === "ETF") return;
        tooltip
          .style("opacity", 1)
          .html(
            '<div class="tt-ticker">' + d.ticker + "</div>" +
            '<div class="tt-name">' + d.name + "</div>" +
            '<div class="tt-sector">' + d.sector + "</div>"
          );
      })
      .on("mousemove", function (event) {
        const rect = container.getBoundingClientRect();
        tooltip
          .style("left", event.clientX - rect.left + 14 + "px")
          .style("top", event.clientY - rect.top - 10 + "px");
      })
      .on("mouseleave", function () {
        tooltip.style("opacity", 0);
      });

    // Labels inside bubbles
    node
      .append("text")
      .attr("class", "bubble-label")
      .text(function (d) { return d.ticker; })
      .style("font-size", function (d) {
        var r = radius(d);
        var len = d.ticker.length;
        var fs = Math.min(r * 0.85, (2 * r) / (len * 0.6));
        return Math.max(7, Math.min(fs, 14)) + "px";
      });

    function ticked() {
      node.attr("transform", function (d) {
        d.x = Math.max(radius(d), Math.min(width - radius(d), d.x));
        d.y = Math.max(radius(d), Math.min(height - radius(d), d.y));
        return "translate(" + d.x + "," + d.y + ")";
      });
    }

    // Legend
    const legend = d3.select(container).append("div").attr("class", "legend");

    sectors.forEach(function (s) {
      const item = legend.append("span").attr("class", "legend-item");
      item
        .append("span")
        .attr("class", "legend-swatch")
        .style("background", sectorColors[s]);
      item.append("span").text(s);
    });
  }

  // -----------------------------------------------------------------------
  // Data table
  // -----------------------------------------------------------------------
  function drawTable(data) {
    const table = d3.select("#stock-table");
    const thead = table.append("thead").append("tr");
    const columns = [
      { key: "ticker", label: "Ticker Symbol" },
      { key: "name", label: "Full Company Name" },
      { key: "sector", label: "Sector" },
      { key: "marketCap", label: "Market Cap" },
    ];

    columns.forEach(function (c) {
      thead.append("th").text(c.label).on("click", function () {
        sortTable(c.key);
      });
    });

    const tbody = table.append("tbody");

    // Initial sort by ticker
    let currentSort = { key: "ticker", asc: true };

    function renderRows() {
      const sorted = data.slice().sort(function (a, b) {
        let va = a[currentSort.key];
        let vb = b[currentSort.key];
        if (currentSort.key === "marketCap") {
          va = va || 0;
          vb = vb || 0;
          return currentSort.asc ? va - vb : vb - va;
        }
        va = (va || "").toString().toLowerCase();
        vb = (vb || "").toString().toLowerCase();
        if (va < vb) return currentSort.asc ? -1 : 1;
        if (va > vb) return currentSort.asc ? 1 : -1;
        return 0;
      });

      tbody.selectAll("tr").remove();

      sorted.forEach(function (d) {
        const tr = tbody
          .append("tr")
          .attr("data-ticker", d.ticker)
          .classed("highlighted", d.ticker === selectedTicker)
          .on("click", function () {
            selectTicker(d.ticker);
          });

        tr.append("td").text(d.ticker);
        tr.append("td").text(d.name);
        tr.append("td").text(d.sector);
        tr.append("td").text(fmtMarketCap(d.marketCap));
      });
    }

    function sortTable(key) {
      if (currentSort.key === key) {
        currentSort.asc = !currentSort.asc;
      } else {
        currentSort = { key: key, asc: true };
      }
      renderRows();
    }

    renderRows();
  }
})();

